-- Fixed-length parts at their alignments, each table's key at 2 704 bytes: `(bool, int2,
-- text)` 2 688, `(uuid, text)` 2 676, `(date, timestamp, text)` 2 676, `(text, interval)`
-- 2 676.
-- @setup
CREATE TABLE f1 (x bool, y int2, a text);
CREATE INDEX f1_i ON f1 (x, y, a);
INSERT INTO f1 VALUES (true, 1, '');
CREATE TABLE f2 (u uuid, a text);
CREATE INDEX f2_i ON f2 (u, a);
INSERT INTO f2 VALUES ('00000000-0000-4000-8000-000000000001', '');
CREATE TABLE f3 (d date, s timestamp, a text);
CREATE INDEX f3_i ON f3 (d, s, a);
INSERT INTO f3 VALUES ('2020-01-01', '2020-01-01 00:00:00', '');
CREATE TABLE f4 (a text, i interval);
CREATE INDEX f4_i ON f4 (a, i);
INSERT INTO f4 VALUES ('', '1 day');
-- @test
SELECT (SELECT count(*) FROM f1) AS c1, (SELECT count(*) FROM f2) AS c2, (SELECT count(*) FROM f3) AS c3, (SELECT count(*) FROM f4) AS c4;
